package org.ruoyi.service.lawyer;

import com.fasterxml.jackson.core.type.TypeReference;
import com.fasterxml.jackson.databind.ObjectMapper;
import lombok.RequiredArgsConstructor;
import org.ruoyi.common.core.exception.ServiceException;
import org.ruoyi.domain.entity.lawyer.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.support.TransactionTemplate;
import java.time.*;
import java.util.*;

/** Durable chunk execution. A recovered in-flight provider call is ambiguous and is never silently repeated. */
@Service @RequiredArgsConstructor
public class DossierClaimExtractor implements DossierJobHandler {
    private final JdbcTemplate jdbc;
    private final TransactionTemplate tx;
    private final DossierMaterialService materials;
    private final DossierAnchorService anchors;
    private final DossierClaimService claims;
    private final DossierClaimModel model;
    private final DossierWorkerModelGate gate;
    private final DossierAiProperties properties;
    private static final ObjectMapper JSON=new ObjectMapper().findAndRegisterModules();
    public static final String PROMPT_VERSION="claims-untrusted-anchors-v1";
    public record Request(List<Long> fileVersionIds,Long modelId,String idempotencyKey){}
    public record Receipt(String runId,String jobId,int readablePages,Integer totalPages,int chunks){}
    public record ScopeData(List<Long> versions,List<String> fingerprints,DossierClaimModel.Route route){}
    public Map<String,Object> budget(Long caseId){var p=anchors.principal(caseId);var rows=jdbc.queryForList("SELECT tokens_charged tokensCharged,pages_charged pagesCharged FROM lawyer_case_ai_budget WHERE tenant_id=? AND user_id=? AND period=?",p.tenantId(),p.userId(),period());var result=new LinkedHashMap<String,Object>();result.put("period",period());result.put("tokenBudget",properties.getTokenBudget());result.put("pageBudget",properties.getPageBudget());result.put("tokensCharged",rows.isEmpty()?0:rows.get(0).get("tokensCharged"));result.put("pagesCharged",rows.isEmpty()?0:rows.get(0).get("pagesCharged"));result.put("method","预留按字符上界估算；实际token未知时不释放预留，不代表已知消耗");return result;}
    public void cancel(Long caseId,Long id){var p=anchors.principal(caseId);tx.executeWithoutResult(s->{var run=requireRun(p,id);materials.cancel(caseId,((Number)run.get("job_id")).longValue());jdbc.update("UPDATE lawyer_case_ai_run SET state='cancelled',error_code='CANCELLED',update_time=UTC_TIMESTAMP() WHERE id=? AND state IN ('queued','running')",id);jdbc.update("UPDATE lawyer_case_ai_chunk SET state='cancelled',error_code='CANCELLED',update_time=UTC_TIMESTAMP() WHERE run_id=? AND state IN ('queued','running')",id);});}
    public List<Map<String,Object>> models(Long caseId){var p=anchors.principal(caseId);var options=new ArrayList<Map<String,Object>>();for(var id:properties.getModelRegions().keySet())try{var route=model.route(p.tenantId(),id);options.add(Map.of("id",id.toString(),"name",route.modelName(),"region",route.region()));}catch(ServiceException ignored){}return options;}
    static <T>T read(String raw,Class<T> type){try{return JSON.readValue(raw,type);}catch(Exception e){throw new ServiceException("任务快照结构无效",422);}}
    static List<String> ids(String raw){try{return JSON.readValue(raw,new TypeReference<List<String>>(){});}catch(Exception e){throw new ServiceException("来源块结构无效",422);}}
    public Receipt request(Long caseId,Request request){var p=anchors.principal(caseId);if(request==null||request.fileVersionIds()==null||request.fileVersionIds().isEmpty()||request.fileVersionIds().size()>20||new HashSet<>(request.fileVersionIds()).size()!=request.fileVersionIds().size()||request.modelId()==null||request.idempotencyKey()==null||!request.idempotencyKey().matches("[A-Za-z0-9_-]{12,64}"))throw new ServiceException("请选择1～20个版本、模型及有效请求标识",400);var route=model.route(p.tenantId(),request.modelId());var versions=request.fileVersionIds().stream().sorted().toList();String requestHash=DossierAnchorService.hash(BankStatementService.json(List.of(versions,route,PROMPT_VERSION)));
        return tx.execute(s->{jdbc.queryForList("SELECT id FROM lawyer_case WHERE tenant_id=? AND id=? AND user_id=? AND deleted=0 FOR UPDATE",p.tenantId(),caseId,p.userId());var prior=jdbc.queryForList("SELECT r.* FROM lawyer_case_ai_run r JOIN lawyer_case_parse_job j ON j.id=r.job_id WHERE j.tenant_id=? AND j.case_id=? AND j.job_type='claims_extract' AND j.idempotency_key=?",p.tenantId(),caseId,request.idempotencyKey());if(!prior.isEmpty()){if(!requestHash.equals(prior.get(0).get("request_hash")))throw new ServiceException("同一请求范围已变化",409);return receipt(prior.get(0));}
            var selected=new ArrayList<CaseFilePage>();var fingerprints=new ArrayList<String>();Integer total=0;for(Long id:versions){var v=anchors.version(p,id);if(!anchors.current(p,v))throw new ServiceException("只可对当前材料版本提取；历史引用请明确固定后人工摘录",409);fingerprints.add(v.getId()+":"+v.getSha256());if(v.getPageCount()==null)total=null;else if(total!=null)total+=v.getPageCount();selected.addAll(materials.pages(caseId,id).stream().filter(page->"success".equals(page.getExtractStatus())&&!DossierAnchorService.text(page).isBlank()).toList());}
            if(selected.isEmpty())throw new ServiceException("没有读取成功的非空页；可重试读取或手工摘录",422);if(selected.size()>100||selected.stream().mapToInt(page->DossierAnchorService.text(page).length()).sum()>300000)throw new ServiceException("本次材料过多，请分批选择（最多100个成功页/30万字符）",422);
            reservePages(p,selected.size());var allAnchors=new ArrayList<CaseSourceAnchor>();for(var page:selected){String text=DossierAnchorService.text(page);for(int start=0;start<text.length();){int end=Math.min(text.length(),start+1400);if(!text.substring(start,end).isBlank())allAnchors.add(anchors.create(p,new DossierAnchorService.Create(page.getFileVersionId(),page.getPageIndex(),"text_offset",start,end,text.substring(start,end),null,null,null,false)));if(end==text.length())break;start=end-80;}}
            long job=DossierMaterialService.id(),run=DossierMaterialService.id();jdbc.update("INSERT INTO lawyer_case_parse_job(id,tenant_id,case_id,user_id,file_version_id,job_type,idempotency_key,requested_pages,create_time,update_time) VALUES(?,?,?,?,?,'claims_extract',?,'[]',UTC_TIMESTAMP(),UTC_TIMESTAMP())",job,p.tenantId(),caseId,p.userId(),versions.get(0),request.idempotencyKey());var scope=new ScopeData(versions,fingerprints,route);int chunks=(allAnchors.size()+5)/6;jdbc.update("INSERT INTO lawyer_case_ai_run(id,tenant_id,case_id,user_id,job_id,purpose,model_id,model_name,provider,endpoint,region,policy_version,prompt_version,scope_json,request_hash,readable_pages,total_pages,chunk_count,create_by,create_time,update_time) VALUES(?,?,?,?,?,'CLAIMS',?,?,?,?,?,'dossier-v1',?,?,?,?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())",run,p.tenantId(),caseId,p.userId(),job,route.id(),route.modelName(),route.provider(),route.endpoint(),route.region(),PROMPT_VERSION,BankStatementService.json(scope),requestHash,selected.size(),total,chunks,p.userId());
            for(int i=0;i<chunks;i++){var batch=allAnchors.subList(i*6,Math.min(allAnchors.size(),i*6+6));var first=batch.get(0);jdbc.update("INSERT INTO lawyer_case_ai_chunk(id,tenant_id,case_id,run_id,chunk_index,file_version_id,page_index,anchors_json,create_time,update_time) VALUES(?,?,?,?,?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())",DossierMaterialService.id(),p.tenantId(),caseId,run,i+1,first.getFileVersionId(),first.getPageIndex(),BankStatementService.json(batch.stream().map(a->a.getId().toString()).toList()));}jdbc.update("UPDATE lawyer_case_parse_job SET progress_total=? WHERE id=?",chunks,job);return new Receipt(Long.toString(run),Long.toString(job),selected.size(),total,chunks);
        });
    }
    static Receipt receipt(Map<String,Object> row){return new Receipt(row.get("id").toString(),row.get("job_id").toString(),((Number)row.get("readable_pages")).intValue(),row.get("total_pages")==null?null:((Number)row.get("total_pages")).intValue(),((Number)row.get("chunk_count")).intValue());}
    static String period(){return java.time.YearMonth.now(ZoneOffset.UTC).toString();}
    void budgetRow(DossierAnchorService.Principal p){jdbc.update("INSERT IGNORE INTO lawyer_case_ai_budget(tenant_id,user_id,period,update_time) VALUES(?,?,?,UTC_TIMESTAMP())",p.tenantId(),p.userId(),period());}
    void reservePages(DossierAnchorService.Principal p,int pages){budgetRow(p);var row=jdbc.queryForMap("SELECT pages_charged FROM lawyer_case_ai_budget WHERE tenant_id=? AND user_id=? AND period=? FOR UPDATE",p.tenantId(),p.userId(),period());if(((Number)row.get("pages_charged")).intValue()+pages>properties.getPageBudget())throw new ServiceException("本月材料页额度不足，请缩小范围或联系管理员",429);jdbc.update("UPDATE lawyer_case_ai_budget SET pages_charged=pages_charged+?,update_time=UTC_TIMESTAMP() WHERE tenant_id=? AND user_id=? AND period=?",pages,p.tenantId(),p.userId(),period());}
    public List<Map<String,Object>> runs(Long caseId){var p=anchors.principal(caseId);return jdbc.queryForList("SELECT CAST(r.id AS CHAR) id,CAST(r.job_id AS CHAR) jobId,CAST(r.model_id AS CHAR) modelId,r.model_name modelName,r.prompt_version promptVersion,r.state,r.readable_pages readablePages,r.total_pages totalPages,r.chunk_count chunkCount,r.successful_chunks successfulChunks,r.failed_chunks failedChunks,r.reserved_tokens reservedTokens,r.actual_tokens actualTokens,r.error_code errorCode,DATE_FORMAT(r.create_time,'%Y-%m-%dT%H:%i:%sZ') createTime,j.error_message errorMessage FROM lawyer_case_ai_run r JOIN lawyer_case_parse_job j ON j.id=r.job_id WHERE r.tenant_id=? AND r.case_id=? AND r.user_id=? ORDER BY r.create_time DESC,r.id DESC LIMIT 30",p.tenantId(),caseId,p.userId());}
    public List<Map<String,Object>> chunks(Long caseId,Long runId){var p=anchors.principal(caseId);requireRun(p,runId);return jdbc.queryForList("SELECT CAST(id AS CHAR) id,chunk_index chunkIndex,state,anchors_json anchorIds,reserved_tokens reservedTokens,input_tokens inputTokens,output_tokens outputTokens,rejection_json rejections,error_code errorCode FROM lawyer_case_ai_chunk WHERE tenant_id=? AND case_id=? AND run_id=? ORDER BY chunk_index",p.tenantId(),caseId,runId);}
    Map<String,Object> requireRun(DossierAnchorService.Principal p,Long id){var rows=jdbc.queryForList("SELECT * FROM lawyer_case_ai_run WHERE id=? AND tenant_id=? AND case_id=? AND user_id=?",id,p.tenantId(),p.caseId(),p.userId());if(rows.isEmpty())throw new ServiceException("任务不可用",404);return rows.get(0);}
    public void retry(Long caseId,Long runId){var p=anchors.principal(caseId);tx.executeWithoutResult(s->{var run=requireRun(p,runId);if(!Set.of("failed","partial","cancelled").contains(run.get("state").toString()))throw new ServiceException("当前任务无需重试",409);jdbc.update("UPDATE lawyer_case_ai_chunk SET state='queued',error_code=NULL,update_time=UTC_TIMESTAMP() WHERE run_id=? AND state IN ('failed','rejected','cancelled')",runId);jdbc.update("UPDATE lawyer_case_ai_run SET state='queued',error_code=NULL,update_time=UTC_TIMESTAMP() WHERE id=?",runId);jdbc.update("UPDATE lawyer_case_parse_job SET state='queued',lease_token=NULL,lease_until=NULL,error_code=NULL,error_message=NULL,update_time=UTC_TIMESTAMP() WHERE id=? AND state NOT IN ('queued','running')",run.get("job_id"));});}
    @Override public boolean supports(String type){return "claims_extract".equals(type);}
    boolean fence(CaseParseJob j,String lease){return !jdbc.queryForList("SELECT j.id FROM lawyer_case_parse_job j JOIN lawyer_case c ON c.id=j.case_id AND c.tenant_id=j.tenant_id AND c.user_id=j.user_id AND c.deleted=0 WHERE j.id=? AND j.lease_token=? AND j.state='running' AND j.lease_until>UTC_TIMESTAMP() FOR UPDATE",j.getId(),lease).isEmpty();}
    @Override public void execute(CaseParseJob job,String lease){var p=new DossierAnchorService.Principal(job.getTenantId(),job.getCaseId(),job.getUserId());var runRows=jdbc.queryForList("SELECT * FROM lawyer_case_ai_run WHERE job_id=? AND tenant_id=? AND case_id=? AND user_id=?",job.getId(),p.tenantId(),p.caseId(),p.userId());if(runRows.isEmpty())throw new DossierReadException("RUN_MISSING","候选任务记录不可用");var run=runRows.get(0);long runId=((Number)run.get("id")).longValue();var scopeData=read(run.get("scope_json").toString(),ScopeData.class);var scope=new DossierOutboundPolicy.Scope(p.tenantId(),p.caseId(),p.userId(),Set.copyOf(scopeData.fingerprints()),DossierOutboundPolicy.Purpose.CLAIMS,scopeData.route().id(),scopeData.route().provider(),scopeData.route().endpoint(),scopeData.route().region(),"dossier-v1");
        tx.executeWithoutResult(s->{if(!fence(job,lease))return;jdbc.update("UPDATE lawyer_case_ai_run SET state='running',update_time=UTC_TIMESTAMP() WHERE id=?",runId);jdbc.update("UPDATE lawyer_case_ai_chunk SET state='failed',error_code='INTERRUPTED_USAGE_UNKNOWN',update_time=UTC_TIMESTAMP() WHERE run_id=? AND state='running'",runId);});
        var chunks=jdbc.queryForList("SELECT * FROM lawyer_case_ai_chunk WHERE run_id=? ORDER BY chunk_index",runId);
        for(var chunk:chunks){if(!"queued".equals(chunk.get("state")))continue;long chunkId=((Number)chunk.get("id")).longValue();boolean submitted=false;long attempt=DossierMaterialService.id();String budgetPeriod=period();try{
            gate.check(job,lease,scope);var offered=ids(chunk.get("anchors_json").toString());var data=new ArrayList<Map<String,Object>>();for(var id:offered){var source=anchors.resolve(p,Long.valueOf(id),true);if(!source.verified())throw new ServiceException("来源指纹或版本变化",409);data.add(Map.of("anchorId",id,"text",source.anchor().getFragmentText(),"kind",source.anchor().getKind()));}String json=BankStatementService.json(data);long reserved=4L*(json.length()+DossierClaimSchema.prompt().length())+2500;
            Boolean reservedOk=tx.execute(s->{if(!fence(job,lease))return false;budgetRow(p);var budget=jdbc.queryForMap("SELECT tokens_charged FROM lawyer_case_ai_budget WHERE tenant_id=? AND user_id=? AND period=? FOR UPDATE",p.tenantId(),p.userId(),period());if(((Number)budget.get("tokens_charged")).longValue()+reserved>properties.getTokenBudget())throw new ServiceException("模型额度不足，请缩小范围或联系管理员",429);jdbc.update("UPDATE lawyer_case_ai_budget SET tokens_charged=tokens_charged+?,update_time=UTC_TIMESTAMP() WHERE tenant_id=? AND user_id=? AND period=?",reserved,p.tenantId(),p.userId(),period());jdbc.update("INSERT INTO lawyer_case_ai_attempt(id,tenant_id,case_id,run_id,chunk_id,period,state,reserved_tokens,create_time,update_time) VALUES(?,?,?,?,?,?,'calling',?,UTC_TIMESTAMP(),UTC_TIMESTAMP())",attempt,p.tenantId(),p.caseId(),runId,chunkId,budgetPeriod,reserved);jdbc.update("UPDATE lawyer_case_ai_chunk SET state='running',reserved_tokens=reserved_tokens+?,update_time=UTC_TIMESTAMP() WHERE id=?",reserved,chunkId);jdbc.update("UPDATE lawyer_case_ai_run SET reserved_tokens=reserved_tokens+? WHERE id=?",reserved,runId);return true;});if(!Boolean.TRUE.equals(reservedOk))return;
            submitted=true;var output=gate.call(job,lease,scope,()->model.generate(p.tenantId(),p.userId(),scopeData.route(),json));
            tx.executeWithoutResult(s->{Long actual=output.inputTokens()==null||output.outputTokens()==null||output.inputTokens()<0||output.outputTokens()<0?null:output.inputTokens()+output.outputTokens();jdbc.update("UPDATE lawyer_case_ai_attempt SET state='returned',input_tokens=?,output_tokens=?,response_hash=?,update_time=UTC_TIMESTAMP() WHERE id=?",output.inputTokens(),output.outputTokens(),output.json()==null?null:DossierAnchorService.hash(output.json()),attempt);if(actual!=null)jdbc.update("UPDATE lawyer_case_ai_budget SET tokens_charged=tokens_charged+?,update_time=UTC_TIMESTAMP() WHERE tenant_id=? AND user_id=? AND period=?",actual-reserved,p.tenantId(),p.userId(),budgetPeriod);});tx.executeWithoutResult(s->{if(!fence(job,lease))return;gate.check(job,lease,scope);jdbc.update("UPDATE lawyer_case_ai_chunk SET input_tokens=?,output_tokens=?,response_json=?,update_time=UTC_TIMESTAMP() WHERE id=?",output.inputTokens(),output.outputTokens(),output.json()!=null&&output.json().length()<=100000?output.json():null,chunkId);var rejection=new ArrayList<String>();try{var candidates=DossierClaimSchema.parse(output.json());var occurrences=new HashMap<String,Integer>();for(var candidate:candidates){String identity=BankStatementService.json(List.of(candidate.kind(),candidate.originalText(),candidate.sources().stream().map(DossierClaimSchema.Link::anchorId).sorted().toList()));int ordinal=occurrences.merge(identity,1,Integer::sum)-1;claims.importCandidate(p,runId,candidate,new HashSet<>(offered),ordinal,rejection);}jdbc.update("UPDATE lawyer_case_ai_chunk SET state=?,rejection_json=?,error_code=? WHERE id=?",rejection.isEmpty()?"success":"rejected",BankStatementService.json(rejection),rejection.isEmpty()?null:"SOURCE_REJECTED",chunkId);}catch(ServiceException e){jdbc.update("UPDATE lawyer_case_ai_chunk SET state='rejected',rejection_json='[\"INVALID_JSON_SCHEMA\"]',error_code='INVALID_JSON_SCHEMA' WHERE id=?",chunkId);}});
        }catch(Exception e){final boolean uncertain=submitted;tx.executeWithoutResult(s->{jdbc.update("UPDATE lawyer_case_ai_attempt SET state='failed_usage_unknown',update_time=UTC_TIMESTAMP() WHERE id=? AND state='calling'",attempt);if(!fence(job,lease))return;String code=e instanceof ServiceException se&&se.getCode()!=null?"REQUEST_"+se.getCode():"MODEL_UNAVAILABLE";jdbc.update("UPDATE lawyer_case_ai_chunk SET state='failed',error_code=?,rejection_json=?,update_time=UTC_TIMESTAMP() WHERE id=?",code,BankStatementService.json(List.of(uncertain?"PROVIDER_USAGE_MAY_BE_UNKNOWN":"NOT_SENT")),chunkId);});}
            tx.executeWithoutResult(s->{if(fence(job,lease))jdbc.update("UPDATE lawyer_case_parse_job SET progress_done=(SELECT COUNT(*) FROM lawyer_case_ai_chunk WHERE run_id=? AND state NOT IN ('queued','running')),update_time=UTC_TIMESTAMP() WHERE id=?",runId,job.getId());});
        }
        tx.executeWithoutResult(s->{if(!fence(job,lease))return;var counts=jdbc.queryForMap("SELECT COUNT(*) total,SUM(state='success') ok,SUM(state<>'success') bad,SUM(input_tokens+output_tokens) tokens,SUM(input_tokens IS NULL OR output_tokens IS NULL) unknown_count FROM lawyer_case_ai_chunk WHERE run_id=?",runId);var usage=jdbc.queryForMap("SELECT COUNT(*) calls,SUM(input_tokens+output_tokens) tokens,SUM(input_tokens IS NULL OR output_tokens IS NULL) unknown_count FROM lawyer_case_ai_attempt WHERE run_id=?",runId);int ok=((Number)counts.get("ok")).intValue(),bad=((Number)counts.get("bad")).intValue();boolean covered=run.get("total_pages")!=null&&((Number)run.get("total_pages")).intValue()==((Number)run.get("readable_pages")).intValue();String state=ok==0?"failed":bad==0&&covered?"success":"partial";jdbc.update("UPDATE lawyer_case_ai_run SET state=?,successful_chunks=?,failed_chunks=?,actual_tokens=?,error_code=?,update_time=UTC_TIMESTAMP() WHERE id=?",state,ok,bad,((Number)usage.get("calls")).intValue()>0&&((Number)usage.get("unknown_count")).intValue()==0?usage.get("tokens"):null,"success".equals(state)?null:"INCOMPLETE_COVERAGE",runId);jdbc.update("UPDATE lawyer_case_parse_job SET state=?,error_code=?,error_message=?,lease_token=NULL,lease_until=NULL,update_time=UTC_TIMESTAMP() WHERE id=?",state,"success".equals(state)?null:"INCOMPLETE_COVERAGE","success".equals(state)?null:"候选处理有缺口：查看失败块、未读取页或手工摘录；不是全案完成",job.getId());});
    }
}
